const update = $('Telegram Trigger').first().json;
const callback = update.callback_query;
const message = update.message;
const text = String(message?.text || '').trim();
const chatId = String(message?.chat?.id || callback?.message?.chat?.id || '');
const messageId = message?.message_id || callback?.message?.message_id || Date.now();
const callbackData = String(callback?.data || '').trim();

const TZ = 'Europe/Zurich';
const DEFAULT_HOUR = 9;
const now = new Date();

const days = {
  domingo: 0,
  lunes: 1,
  martes: 2,
  miércoles: 3,
  miercoles: 3,
  jueves: 4,
  viernes: 5,
  sábado: 6,
  sabado: 6,
};

const dayNames = [
  'Domingo', 'Lunes', 'Martes', 'Miércoles',
  'Jueves', 'Viernes', 'Sábado'
];

const months = {
  enero: 1, febrero: 2, marzo: 3, abril: 4,
  mayo: 5, junio: 6, julio: 7, agosto: 8,
  septiembre: 9, setiembre: 9, octubre: 10,
  noviembre: 11, diciembre: 12,
};

const numberWords = {
  una: 1, uno: 1, dos: 2, tres: 3, cuatro: 4,
  cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9,
  diez: 10, once: 11, doce: 12, trece: 13,
  catorce: 14, quince: 15, dieciseis: 16, dieciséis: 16,
  diecisiete: 17, dieciocho: 18, diecinueve: 19,
  veinte: 20, veintiuna: 21, veintiuno: 21,
  veintidós: 22, veintidos: 22, veintitrés: 23, veintitres: 23,
};

const pad = n => String(n).padStart(2, '0');

function zonedParts(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);

  const out = {};
  for (const p of parts) {
    if (p.type !== 'literal') out[p.type] = Number(p.value);
  }
  return out;
}

function tzOffsetMs(date) {
  const p = zonedParts(date);
  const asUTC = Date.UTC(
    p.year, p.month - 1, p.day,
    p.hour, p.minute, p.second
  );
  return asUTC - date.getTime();
}

function localDate(y, m, d, h = 0, min = 0, sec = 0) {
  const wall = Date.UTC(y, m - 1, d, h, min, sec);
  let probe = new Date(wall);
  let offset = tzOffsetMs(probe);
  let result = new Date(wall - offset);
  const offset2 = tzOffsetMs(result);
  if (offset2 !== offset) result = new Date(wall - offset2);
  return result;
}

function addLocalDays(ymd, amount) {
  const d = new Date(Date.UTC(ymd.year, ymd.month - 1, ymd.day + amount));
  return {
    year: d.getUTCFullYear(),
    month: d.getUTCMonth() + 1,
    day: d.getUTCDate(),
  };
}

function weekdayOf(ymd) {
  return new Date(Date.UTC(ymd.year, ymd.month - 1, ymd.day)).getUTCDay();
}

function ymdIso(ymd) {
  return `${ymd.year}-${pad(ymd.month)}-${pad(ymd.day)}`;
}

function calculateDefaultReminder(eventDate) {
  const twoHoursBefore = new Date(eventDate.getTime() - 2 * 60 * 60 * 1000);
  const ep = zonedParts(eventDate);
  const nineAM = localDate(ep.year, ep.month, ep.day, 9, 0, 0);

  let remindAt = twoHoursBefore > nineAM ? nineAM : twoHoursBefore;

  if (remindAt <= now && eventDate > now) {
    remindAt = twoHoursBefore > now ? twoHoursBefore : new Date(eventDate);
  }

  return remindAt;
}

function recurrenceFromText(value) {
  if (/\b(cada\s+d[ií]a|diariamente|diario)\b/i.test(value)) return 'daily';
  if (/\b(cada\s+semana|semanalmente|semanal)\b/i.test(value)) return 'weekly';
  if (/\b(cada\s+mes|mensualmente|mensual)\b/i.test(value)) return 'monthly';
  if (/\b(cada\s+a[ñn]o|anualmente|anual|todos\s+los\s+a[ñn]os)\b/i.test(value)) return 'yearly';
  return 'none';
}

function customAdvance(value) {
  const m = value.match(
    /\b(?:av[ií]same|avisame|recu[eé]rdame)\s+(?:con\s+)?(\d+)\s*(min(?:uto)?s?|h(?:ora)?s?|d[ií]as?|semanas?)\s+antes\b/i
  );
  if (!m) return null;

  const amount = Number(m[1]);
  const unit = m[2].toLowerCase();

  if (unit.startsWith('min')) return amount;
  if (unit.startsWith('h')) return amount * 60;
  if (unit.startsWith('d')) return amount * 24 * 60;
  if (unit.startsWith('sem')) return amount * 7 * 24 * 60;
  return null;
}

function cleanTitle(value) {
  const monthNames = Object.keys(months).join('|');
  const numberWordRegex = Object.keys(numberWords).join('|');

  let result = String(value || '');

  result = result
    .replace(/\b(cada\s+d[ií]a|diariamente|diario|cada\s+semana|semanalmente|semanal|cada\s+mes|mensualmente|mensual|cada\s+a[ñn]o|anualmente|anual|todos\s+los\s+a[ñn]os)\b/gi, '')
    .replace(/\b(?:av[ií]same|avisame|recu[eé]rdame)\s+(?:con\s+)?\d+\s*(?:min(?:uto)?s?|h(?:ora)?s?|d[ií]as?|semanas?)\s+antes\b/gi, '')
    .replace(/\bpasado\s+mañana\b/gi, '')
    .replace(/\b(hoy|mañana)\b/gi, '')
    .replace(/\b(domingo|lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado)\b/gi, '')
    .replace(/\b\d{1,2}[\/-]\d{1,2}(?:[\/-]\d{2,4})?\b/g, '')
    .replace(new RegExp(`\\b\\d{1,2}\\s+(?:de\\s+)?(?:${monthNames})(?:\\s+(?:de\\s+)?\\d{4})?\\b`, 'gi'), '')
    .replace(/\ba\s+las?\s+\d{1,2}(?::[0-5]\d)?\b/gi, '')
    .replace(/\b([01]?\d|2[0-3]):[0-5]\d\b/g, '')
    .replace(new RegExp(`\\ba\\s+las?\\s+(?:${numberWordRegex})\\b`, 'gi'), '')
    .replace(/^\s*recuerda\s+que\s+/i, '')
    .replace(/^\s*recu[eé]rdame\s+/i, '')
    .replace(/^\s*recordatorio\s*:?\s*/i, '')
    .replace(/^\s*tenemos\s+/i, '')
    .replace(/^\s*hay\s+/i, '')
    .replace(/^\s*(el|la)\s+/i, '')
    .replace(/\s+/g, ' ')
    .replace(/\s+([?.!,])/g, '$1')
    .replace(/^[,.;:¿?¡!\s]+|[,.;:¿?¡!\s]+$/g, '')
    .trim();

  result = result || 'Recordatorio';
  return result.charAt(0).toUpperCase() + result.slice(1);
}

function listRange(value) {
  const t = value.toLowerCase();

  if (/^\/?hoy$/.test(t) || /\b(recordatorios?|qu[eé]\s+tengo|mu[eé]strame|lista).*\bhoy\b/i.test(value)) {
    return 'today';
  }
  if (/^\/?ma[ñn]ana$/.test(t) || /\b(recordatorios?|qu[eé]\s+tengo|mu[eé]strame|lista).*\bma[ñn]ana\b/i.test(value)) {
    return 'tomorrow';
  }
  if (/^\/?(proxima|próxima)$/.test(t) || /\b(pr[oó]xima|siguiente)\s+semana\b/i.test(value)) {
    return 'next_week';
  }
  if (/^\/?semana$/.test(t) || /\b(esta|la)\s+semana\b/i.test(value)) {
    return 'this_week';
  }
  if (
    /^\/?(todos|recordatorios)$/.test(t) ||
    /\b(todos?|lista|mu[eé]strame|ens[eé][ñn]ame).*(recordatorios?)\b/i.test(value) ||
    /\brecordatorios?\s+en\s+general\b/i.test(value)
  ) {
    return 'all';
  }

  return '';
}

// ----- CALLBACKS -----
if (callbackData) {
  if (callbackData.startsWith('cancel:')) {
    return [{
      json: {
        action: 'cancel',
        chatId,
        reminderId: callbackData.split(':')[1],
      }
    }];
  }

  if (callbackData.startsWith('add_alert:')) {
    return [{
      json: {
        action: 'alert_menu',
        chatId,
        reminderId: callbackData.split(':')[1],
      }
    }];
  }

  const alertMatch = callbackData.match(/^alert_(5m|15m|1h|2h|1d|1w):(.+)$/);
  if (alertMatch) {
    const amounts = {
      '5m': [5, '5 min'],
      '15m': [15, '15 min'],
      '1h': [60, '1 hora'],
      '2h': [120, '2 horas'],
      '1d': [1440, '1 día'],
      '1w': [10080, '1 semana'],
    };

    return [{
      json: {
        action: 'add_alert',
        chatId,
        reminderId: alertMatch[2],
        minutesBefore: amounts[alertMatch[1]][0],
        alertLabel: amounts[alertMatch[1]][1],
      }
    }];
  }

  return [{
    json: {
      action: 'reply',
      chatId,
      replyText: 'No reconozco ese botón.',
    }
  }];
}

if (!text) {
  return [{
    json: {
      action: 'reply',
      chatId,
      replyText: 'Envíame un recordatorio por texto.',
    }
  }];
}

// ----- CONSULTAS -----
const range = listRange(text);
if (range) {
  return [{
    json: {
      action: 'list',
      chatId,
      range,
    }
  }];
}

const nowLocal = zonedParts(now);
const todayYmd = {
  year: nowLocal.year,
  month: nowLocal.month,
  day: nowLocal.day,
};

// ----- VARIOS EVENTOS EN UN MENSAJE -----
const rawLines = text
  .split(/\n+/)
  .map(line => line.trim())
  .filter(Boolean);

const timeToken = '(\\d{1,2})(?::([0-5]\\d))?';
const eventLineRegex = new RegExp(
  `\\b(domingo|lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado)\\b.*?\\b(?:de\\s+)?${timeToken}\\s+(?:a|hasta)\\s+(?:las?\\s+)?${timeToken}(?:\\s*\\(([^)]+)\\))?`,
  'i'
);

const firstEventIndex = rawLines.findIndex(line => eventLineRegex.test(line));
const multiEvents = [];
const recurrenceType = recurrenceFromText(text);

if (firstEventIndex >= 0) {
  let baseTitle = 'Evento';

  if (firstEventIndex > 0) {
    const context = rawLines
      .slice(0, firstEventIndex)
      .filter(line => !/^(entonces\s+hacemos|hacemos|quedamos|vale|ok|perfecto)\s*:?\s*$/i.test(line));

    if (context.length) {
      baseTitle = cleanTitle(context[0].replace(/[:\-–—]+$/g, ''));
    }
  }

  for (const line of rawLines.slice(firstEventIndex)) {
    const match = line.match(eventLineRegex);
    if (!match) continue;

    const dayName = match[1].toLowerCase();
    const startHour = Number(match[2]);
    const startMinute = Number(match[3] || 0);
    const endHour = Number(match[4]);
    const endMinute = Number(match[5] || 0);
    const extra = String(match[6] || '').trim();

    if (startHour > 23 || endHour > 23) continue;

    let diff = (days[dayName] - weekdayOf(todayYmd) + 7) % 7;
    let eventYmd = addLocalDays(todayYmd, diff);
    let eventDate = localDate(
      eventYmd.year, eventYmd.month, eventYmd.day,
      startHour, startMinute
    );

    if (diff === 0 && eventDate <= now) {
      eventYmd = addLocalDays(todayYmd, 7);
      eventDate = localDate(
        eventYmd.year, eventYmd.month, eventYmd.day,
        startHour, startMinute
      );
    }

    let thisTitle = baseTitle;
    if (thisTitle === 'Evento') {
      const weekdayMatch = line.match(
        /\b(domingo|lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado)\b/i
      );
      if (weekdayMatch && weekdayMatch.index > 0) {
        const prefix = line.slice(0, weekdayMatch.index)
          .replace(/[:\-–—]+$/g, '')
          .trim();
        if (prefix) thisTitle = cleanTitle(prefix);
      }
    }

    const eventLabel =
      `${dayNames[weekdayOf(eventYmd)]} ${eventYmd.day} · ` +
      `${pad(startHour)}:${pad(startMinute)}–${pad(endHour)}:${pad(endMinute)}`;

    const alertMinutes = customAdvance(text);
    const defaultAt = calculateDefaultReminder(eventDate);

    multiEvents.push({
      json: {
        action: 'create',
        chatId,
        payload: {
          title: extra ? `${thisTitle} — ${extra.toUpperCase()}` : thisTitle,
          description: eventLabel,
          emoji: '⏰',
          type: 'event',
          targetDate: ymdIso(eventYmd),
          targetTime: `${pad(startHour)}:${pad(startMinute)}`,
          timezone: TZ,
          source: {
            type: 'telegram',
            externalId: `telegram-${messageId}-${multiEvents.length + 1}`,
            metadata: {
              telegramChatId: chatId,
              telegramMessageId: messageId,
              eventLabel,
              endTime: `${pad(endHour)}:${pad(endMinute)}`,
            },
          },
          alerts: alertMinutes !== null
            ? [{
                mode: 'relative',
                minutesBefore: alertMinutes,
                channel: 'telegram',
              }]
            : [{
                mode: 'absolute',
                notifyAt: defaultAt.toISOString(),
                channel: 'telegram',
              }],
          recurrence: {
            type: recurrenceType,
            startDate: ymdIso(eventYmd),
            endDate: '',
            dailyTargetCount: 1,
            rule: {},
          },
          status: 'pending',
        },
      },
      pairedItem: { item: 0 },
    });
  }

  if (multiEvents.length) {
    multiEvents.sort((a, b) => {
      const da = `${a.json.payload.targetDate}T${a.json.payload.targetTime || '00:00'}`;
      const db = `${b.json.payload.targetDate}T${b.json.payload.targetTime || '00:00'}`;
      return da.localeCompare(db);
    });
    return multiEvents;
  }
}

// ----- UN EVENTO -----
let eventYmd = { ...todayYmd };
let foundDate = false;
let foundTime = false;
let weekdayRequested = null;
let explicitYear = false;

const relativeDelay = text.match(
  /\ben\s+(\d+)\s*(min(?:uto)?s?|h(?:ora)?s?|d[ií]as?|semanas?)\b/i
);

if (relativeDelay) {
  const amount = Number(relativeDelay[1]);
  const unit = relativeDelay[2].toLowerCase();
  let ms = 0;

  if (unit.startsWith('min')) ms = amount * 60 * 1000;
  else if (unit.startsWith('h')) ms = amount * 60 * 60 * 1000;
  else if (unit.startsWith('d')) ms = amount * 24 * 60 * 60 * 1000;
  else if (unit.startsWith('sem')) ms = amount * 7 * 24 * 60 * 60 * 1000;

  const target = new Date(now.getTime() + ms);
  const p = zonedParts(target);
  eventYmd = { year: p.year, month: p.month, day: p.day };

  const payload = {
    title: cleanTitle(text.replace(relativeDelay[0], '')),
    description: '',
    emoji: '⏰',
    type: 'normal',
    targetDate: ymdIso(eventYmd),
    targetTime: `${pad(p.hour)}:${pad(p.minute)}`,
    timezone: TZ,
    source: {
      type: 'telegram',
      externalId: `telegram-${messageId}`,
      metadata: {
        telegramChatId: chatId,
        telegramMessageId: messageId,
      },
    },
    alerts: [{
      mode: 'absolute',
      notifyAt: target.toISOString(),
      channel: 'telegram',
    }],
    recurrence: {
      type: recurrenceFromText(text),
      startDate: ymdIso(eventYmd),
      endDate: '',
      dailyTargetCount: 1,
      rule: {},
    },
    status: 'pending',
  };

  return [{
    json: { action: 'create', chatId, payload },
    pairedItem: { item: 0 },
  }];
}

if (/\bhoy\b/i.test(text)) foundDate = true;

if (/\bpasado\s+mañana\b/i.test(text)) {
  eventYmd = addLocalDays(todayYmd, 2);
  foundDate = true;
} else if (/\bmañana\b/i.test(text)) {
  eventYmd = addLocalDays(todayYmd, 1);
  foundDate = true;
}

const numericDate = text.match(
  /\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/
);

if (numericDate) {
  const day = Number(numericDate[1]);
  const month = Number(numericDate[2]);
  let year = numericDate[3] ? Number(numericDate[3]) : nowLocal.year;

  explicitYear = Boolean(numericDate[3]);
  if (year < 100) year += 2000;

  eventYmd = { year, month, day };

  if (!explicitYear) {
    const candidate = localDate(year, month, day, 23, 59, 59);
    if (candidate < now) eventYmd.year += 1;
  }
  foundDate = true;
}

const monthNames = Object.keys(months).join('|');
const writtenDate = text.match(
  new RegExp(
    `\\b(\\d{1,2})\\s+(?:de\\s+)?(${monthNames})(?:\\s+(?:de\\s+)?(\\d{4}))?\\b`,
    'i'
  )
);

if (writtenDate) {
  const day = Number(writtenDate[1]);
  const month = months[writtenDate[2].toLowerCase()];
  let year = writtenDate[3] ? Number(writtenDate[3]) : nowLocal.year;

  explicitYear = Boolean(writtenDate[3]);
  eventYmd = { year, month, day };

  if (!explicitYear) {
    const candidate = localDate(year, month, day, 23, 59, 59);
    if (candidate < now) eventYmd.year += 1;
  }
  foundDate = true;
}

if (
  !numericDate &&
  !writtenDate &&
  !/\b(hoy|mañana|pasado\s+mañana)\b/i.test(text)
) {
  for (const [name, dayNumber] of Object.entries(days)) {
    if (new RegExp(`\\b${name}\\b`, 'i').test(text)) {
      weekdayRequested = dayNumber;
      foundDate = true;
      break;
    }
  }
}

let hour = null;
let minute = 0;

const colonTime = text.match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/);
if (colonTime) {
  hour = Number(colonTime[1]);
  minute = Number(colonTime[2]);
  foundTime = true;
}

if (!foundTime) {
  const simpleTime = text.match(/\ba\s+las?\s+(\d{1,2})(?:[:.]([0-5]\d))?\b/i);
  if (simpleTime) {
    hour = Number(simpleTime[1]);
    minute = Number(simpleTime[2] || 0);
    foundTime = hour <= 23;
  }
}

if (!foundTime) {
  const words = Object.keys(numberWords).join('|');
  const wordTime = text.match(
    new RegExp(`\\ba\\s+las?\\s+(${words})\\b`, 'i')
  );
  if (wordTime) {
    hour = numberWords[wordTime[1].toLowerCase()];
    minute = 0;
    foundTime = true;
  }
}

if (!foundTime) {
  hour = DEFAULT_HOUR;
  minute = 0;
}

if (weekdayRequested !== null) {
  let diff = (weekdayRequested - weekdayOf(todayYmd) + 7) % 7;
  eventYmd = addLocalDays(todayYmd, diff);

  const candidate = localDate(
    eventYmd.year, eventYmd.month, eventYmd.day,
    hour, minute
  );

  if (diff === 0 && candidate <= now) {
    eventYmd = addLocalDays(todayYmd, 7);
  }
}

let eventDate = localDate(
  eventYmd.year, eventYmd.month, eventYmd.day,
  hour, minute
);

if (!foundDate && eventDate <= now) {
  eventYmd = addLocalDays(todayYmd, 1);
  eventDate = localDate(
    eventYmd.year, eventYmd.month, eventYmd.day,
    hour, minute
  );
}

if (foundDate && explicitYear && eventDate < now) {
  return [{
    json: {
      action: 'reply',
      chatId,
      replyText: 'Esa fecha ya pasó.',
    }
  }];
}

const alertMinutes = customAdvance(text);
let alerts;

if (alertMinutes !== null) {
  alerts = [{
    mode: 'relative',
    minutesBefore: alertMinutes,
    channel: 'telegram',
  }];
} else if (!foundTime) {
  const remindAt = localDate(
    eventYmd.year, eventYmd.month, eventYmd.day,
    9, 0
  );

  alerts = [{
    mode: 'absolute',
    notifyAt: remindAt.toISOString(),
    channel: 'telegram',
  }];
} else {
  alerts = [{
    mode: 'absolute',
    notifyAt: calculateDefaultReminder(eventDate).toISOString(),
    channel: 'telegram',
  }];
}

const title = cleanTitle(text);
const recurrence = recurrenceFromText(text);

const payload = {
  title,
  description: '',
  emoji: '⏰',
  type: 'normal',
  targetDate: ymdIso(eventYmd),
  targetTime: foundTime ? `${pad(hour)}:${pad(minute)}` : '',
  timezone: TZ,
  source: {
    type: 'telegram',
    externalId: `telegram-${messageId}`,
    metadata: {
      telegramChatId: chatId,
      telegramMessageId: messageId,
    },
  },
  alerts,
  recurrence: {
    type: recurrence,
    startDate: ymdIso(eventYmd),
    endDate: '',
    dailyTargetCount: 1,
    rule: {},
  },
  status: 'pending',
};

return [{
  json: {
    action: 'create',
    chatId,
    payload,
  },
  pairedItem: { item: 0 },
}];

const response = $json || {};
const reminders = Array.isArray(response.reminders) ? response.reminders : [];
const total = Number(response.total || reminders.length || 0);
const range = String(response.range || 'all');

const labels = {
  today: 'Recordatorios de hoy',
  tomorrow: 'Recordatorios de mañana',
  this_week: 'Recordatorios de esta semana',
  next_week: 'Recordatorios de la próxima semana',
  all: 'Recordatorios pendientes',
};

if (!reminders.length) {
  return [{
    json: {
      text: `📭 ${labels[range] || labels.all}: ninguno.`,
    }
  }];
}

const recurrenceIcon = {
  daily: ' ↻ diario',
  weekly: ' ↻ semanal',
  monthly: ' ↻ mensual',
  yearly: ' ↻ anual',
  custom: ' ↻',
};

const rows = reminders.map((r, i) => {
  const date = String(r.targetDate || '');
  const time = String(r.targetTime || '');
  const when = `${date}${time ? ` · ${time}` : ''}`;
  const recurrence = recurrenceIcon[r?.recurrence?.type] || '';
  return `${i + 1}. ${r.emoji || '⏰'} ${r.title}\n   ${when}${recurrence}`;
});

let text = `📋 ${labels[range] || labels.all} (${total})\n\n${rows.join('\n\n')}`;

if (total > reminders.length) {
  text += `\n\n…mostrando ${reminders.length} de ${total}.`;
}

return [{ json: { text } }];

const alerts = Array.isArray($json.alerts) ? $json.alerts : [];
return alerts.map((alert) => ({
  json: alert,
  pairedItem: { item: 0 },
}));
